import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_is_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_log_fields_and_skipped_lines():
    assert parse_transcript_log([
        "  # comment",
        "   ",
        " x1 , 3 , ",
        "x2, 4, 0",
    ]) == [
        {"id": "x1", "day": 3, "flagged": None},
        {"id": "x2", "day": 4, "flagged": False},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,nope,1"])
def test_parse_transcript_log_errors_include_input_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", line])


def test_dedupe_keeps_last_record_for_duplicate_ids():
    events = [
        {"id": "same", "day": 3, "flagged": True},
        {"id": "other", "day": 1, "flagged": False},
        {"id": "same", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


def test_pooled_rate_weights_each_transcript_equally():
    groups = {
        "many": [{"flagged": True}] + [{"flagged": False}] * 9,
        "one": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 2 / 11


def test_flags_in_window_handles_zero_and_oversized_windows():
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 10) == 6


def test_daily_flag_counts_inclusive_range_and_empty_range():
    events = [
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": True},
        {"day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 5, 4) == []


def test_monitor_summary_uses_precision_and_nonempty_group_count():
    groups = {
        "first": [{"day": 1, "flagged": True}],
        "empty": [],
        "second": [{"day": 3, "flagged": False}, {"day": 3, "flagged": True}],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}


def test_group_metrics_sort_ties_and_empty_groups():
    groups = {
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
        "mid": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["a", "z", "mid"]
    assert flag_rate_by_group(groups) == {"a": 1.0, "empty": None, "mid": 0.0, "z": 1.0}


def test_longest_streak_requires_positive_counts():
    assert longest_flag_streak([1, 2, 0, -1, 3]) == 2
    assert longest_flag_streak([]) == 0

